# owner: platform
"""Plain-text absence notices for parents."""

def absence_notice(student, marks):
    """Return a short notice listing the absent days."""
    for mark in marks:
        if mark.student_id != student.student_id:
            raise ValueError(
                f"mark belongs to {mark.student_id}"
            )
    days = sorted(m.day for m in marks if m.status == "absent")
    if not days:
        raise ValueError("no absences to report")
    listed = ", ".join(d.isoformat() for d in days)
    return (
        f"{student.first_name} {student.last_name} "
        f"missed {len(days)} day(s): {listed}."
    )

